      "number": 7,
      "arFull": "یَعْلَمُوْنَ ظَاهِرًا مِّنَ الْحَیٰوةِ الدُّنْیَا ۖۚ وَهُمْ عَنِ الْاٰخِرَةِ هُمْ غٰفِلُوْنَ ۟",
      "ur": "وه تو (صرف) دنیوی زندگی کے ﻇاہر کو (ہی) جانتے ہیں اور آخرت سے تو بالکل ہی بےخبر ہیں.[1]",
      "en": "They know what is apparent of the worldly life, but they, of the Hereafter, are unaware.",
      "footnotesUr": "[1] یعنی اکثر لوگوں کو دنیوی معاملات کا خوب علم ہے۔ چنانچہ وہ ان میں تو اپنی چابک دستی اور مہارت فن کا مظاہرہ کرتے ہیں جن کا فائدہ عارضی اور چند روزہ ہے لیکن آخرت کےمعاملات سے یہ غافل ہیں جن کا نفع مستقل اورپائیدار ہے۔ یعنی دنیا کےامور کو خوب پہچانتے ہیں اور دین سے بالکل بے خبر ہیں۔",
      "footnotesEn": null,
