      "footnotesUr": "[1] اس سے مراد ہر فرد کا دوسرے فرد سے الگ ہونا نہیں ہے۔ بلکہ مطلب مومنوں کا اور کافروں کا الگ الگ ہونا ہے۔ اہل ایمان جنت میں اور اہل کفر وشرک جہنم میں چلے جائیں گے اور ان کے درمیان دائمی جدائی ہو جائے گی، یہ دونوں پھر کبھی اکھٹے نہیں ہوں گے یہ حساب کے بعد ہوگا۔ چنانچہ اسی علیحدگی کی وضاحت اگلی آیات میں کی جا رہی ہے۔",
