      "arFull": "وَاَمَّا الَّذِیْنَ كَفَرُوْا وَكَذَّبُوْا بِاٰیٰتِنَا وَلِقَآئِ الْاٰخِرَةِ فَاُولٰٓىِٕكَ فِی الْعَذَابِ مُحْضَرُوْنَ ۟",
