      "ur": "تمام تعریفوں کے ﻻئق آسمان وزمین میں صرف وہی ہے تیسرے پہر کو اور ﻇہر کے وقت بھی (اس کی پاکیزگی بیان کرو).[1]",
      "en": "And to Him is [due all] praise throughout the heavens and the earth. And [exalted is He] at night and when you are at noon.",
      "footnotesUr": "[1] یہ اللہ تعالیٰ کی طرف سے اپنی ذات مقدسہ کے لئے تسبیح وتحمید ہے، جس سے مقصد اپنے بندوں کی رہنمائی ہے کہ ان اوقات میں، جو ایک دوسرے کے پیچھے آتے ہیں اور جو اس کے کمال قدرت وعظمت پر دلالت کرتے ہیں، اس کی تسبیح وتحمید کیا کرو، شام کا وقت، رات کی تاریکی کا پیش خیمہ اور سپیدۂ سحر دن کی روشنی کا پیامبر ہوتا ہے۔ عشاء، شدت تاریکی کا اور ظہر، خوب روشن ہو جانے کا وقت ہے۔ پس وہ ذات پاک ہےجو ان سب کی خالق ہے اور جس نے ان تمام اوقات میں الگ الگ فوائد رکھے ہیں۔ بعض کہتے ہیں کہ تسبیح سے مراد، نماز ہے اور دونوں آیات میں مذکور اوقات پانچ نمازوں کے اوقات ہیں۔ تُمْسُونَ میں مغرب وعشاء، تُصْبِحُونَ میں نماز فجر، عَشِيًّا (سہ پہر) میں عصر اور تُظْهِرُونَ میں نماز ظہر آجاتی ہے، (فتح القدیر) ایک ضعیف حدیث میں ان دونوں آیات کو صبح وشام پڑھنے کی یہ فضیلت بیان ہوئی ہے کہ اس سے شب وروز کی کوتاہیوں کا ازلہ ہوتا ہے۔ (أبو داود ، كتاب الأدب ، باب ما يقول إذا أصبح)۔",
