      "number": 37,
      "arFull": "اَوَلَمْ یَرَوْا اَنَّ اللّٰهَ یَبْسُطُ الرِّزْقَ لِمَنْ یَّشَآءُ وَیَقْدِرُ ؕ اِنَّ فِیْ ذٰلِكَ لَاٰیٰتٍ لِّقَوْمٍ یُّؤْمِنُوْنَ ۟",
      "ur": "کیا انہوں نے نہیں دیکھا کہ اللہ تعالیٰ جسے چاہے کشاده روزی دیتا ہے اور جسے چاہے تنگ[1] ، اس میں بھی ان لوگوں کے لئے جو ایمان ﻻتے ہیں نشانیاں ہیں.",
      "en": "Do they not see that Allāh extends provision for whom He wills and restricts [it]? Indeed in that are signs for a people who believe.",
      "footnotesUr": "[1] یعنی اپنی حکمت ومصلحت سے وہ کسی کو مال ودولت زیادہ اور کسی کوکم دیتا ہے۔ حتیٰ کہ بعض دفعہ عقل وشعور میں اور ظاہری اسباب ووسائل میں دو انسان ایک جیسے ہی محسوس ہوتے ہیں، ایک جیسا ہی کاروبار بھی شروع کرتے ہیں۔ لیکن ایک کے کاروبار کو خوب فروغ ملتا ہے اور اس کےوارے نیارے ہو جاتے ہیں، جب کہ دوسرےشخص کا کاروبار محدود ہی رہتا ہے اور اسے وسعت نصیب نہیں ہوتی۔ آخر یہ کون ہستی ہے، جس کے پاس تمام اختیارات ہیں اور وہ اس قسم کے تصرفات فرماتا ہے۔ علاوہ ازیں وہ کبھی دولت فراواں کے مالک کو محتاج اور محتاج کو مال ودولت سے نواز دیتا ہے۔ یہ سب اسی ایک اللہ کے ہاتھ میں ہے جس کا کوئی شریک نہیں۔",
