      "number": 48,
      "arFull": "اَللّٰهُ الَّذِیْ یُرْسِلُ الرِّیٰحَ فَتُثِیْرُ سَحَابًا فَیَبْسُطُهٗ فِی السَّمَآءِ كَیْفَ یَشَآءُ وَیَجْعَلُهٗ كِسَفًا فَتَرَی الْوَدْقَ یَخْرُجُ مِنْ خِلٰلِهٖ ۚ فَاِذَاۤ اَصَابَ بِهٖ مَنْ یَّشَآءُ مِنْ عِبَادِهٖۤ اِذَا هُمْ یَسْتَبْشِرُوْنَ ۟ۚ",
      "ur": "اللہ تعالیٰ ہوائیں چلاتا ہے وه ابر کو اٹھاتی ہیں[1] پھر اللہ تعالیٰ اپنی منشا کے مطابق اسے آسمان میں پھیلا دیتا ہے [2]اور اس کے ٹکڑے ٹکڑے کر دیتا ہے[3] پھر آپ دیکھتے ہیں کہ اس کےاندر سے قطرے نکلتے ہیں،[4] اور جنہیں اللہ چاہتا ہے ان بندوں پر پانی برساتا ہے تو وه خوش خوش ہو جاتے ہیں۔",
      "en": "It is Allāh who sends the winds, and they stir the clouds and spread them in the sky however He wills, and He makes them fragments so you see the rain emerge from within them. And when He causes it to fall upon whom He wills of His servants, immediately they rejoice",
      "footnotesUr": "[1] یعنی وہ بادل جہاں بھی ہوتے ہیں، وہاں سے ہوائیں ان کو اٹھا کر لے جاتی ہیں۔\n[2] کبھی چلا کر، کبھی ٹھہرا کر، کبھی تہ بہ تہ کرکے، کبھی دور دراز تک۔ یہ آسمان پر بادلوں کی مختلف کیفیتیں ہوتی ہیں۔\n[3] یعنی ان کو آسمان پر پھیلانے کے بعد، کبھی ان کو مختلف ٹکڑوں میں تقسیم کر دیتا ہے۔\n[4] وَدْقٌ کے معنی بارش کے ہیں، یعنی ان بادلوں سے اللہ اگر چاہتا ہے تو بارش ہو جاتی ہے، جس سے بارش کے ضرورت مند خوش ہو جاتے ہیں۔",
